<?php declare(strict_types=1);
$electronicInvoiceMessages=isset($nativeAccess)?(new \Kulturhus\Native\Language\Catalog($db,$nativeAccess))->messages():[];$electronicInvoiceText=static fn(string$s,array$v=[]):string=>\Kulturhus\Native\Language\ElectronicInvoiceMessages::text($s,$electronicInvoiceMessages,$v);
$invoiceMessages=(new \Kulturhus\Verein\InvoiceMailView($db,(string)$_SESSION['actor']))->listing($mailDocumentId);
foreach($invoiceMessages as $invoiceMessage): ?>
<section class="card" data-invoice-mail-preview><link rel="stylesheet" href="xml-text-preview.css?v=2"><h3><?=e($electronicInvoiceText('Begleit-E-Mail zur Rechnung'))?></h3><?php if(!$invoiceMessage['available']): ?><p><?=e($electronicInvoiceText('Die Originalmail enthält weitere geschützte Unterlagen oder ist nicht verfügbar. Sie kann mit diesem Zugang nicht geöffnet werden.'))?></p><?php else: $workflow=$invoiceMessage['workflow']; ?><p><strong><?=e($electronicInvoiceText($workflow['complete']?'Alle Belege dieser E-Mail sind bearbeitet.':'Diese E-Mail enthält noch offene Belege.'))?></strong><br><?=e($electronicInvoiceText('{total} Belege: {open} offen, {assigned} zugeordnet, {archived} archiviert.',['total'=>(string)(int)$workflow['total'],'open'=>(string)(int)$workflow['counts']['open'],'assigned'=>(string)(int)$workflow['counts']['assigned'],'archived'=>(string)(int)$workflow['counts']['archived']]))?></p><ul><?php foreach($workflow['documents'] as $related): ?><li><a href="<?= e(url(['view'=>'finance','tab'=>'inbox','inbox_doc'=>$related['id'],'status'=>$related['status']])) ?>"><?= e($related['title']) ?></a> — <?=e($electronicInvoiceText(['open'=>'Offen','assigned'=>'Zugeordnet','archived'=>'Archiviert'][$related['status']]))?></li><?php endforeach ?></ul><dl class="data-list"><dt><?=e($electronicInvoiceText('Von'))?></dt><dd class="doc-path"><?= e($invoiceMessage['from']) ?></dd><dt><?=e($electronicInvoiceText('An'))?></dt><dd class="doc-path"><?= e($invoiceMessage['to']) ?></dd><dt><?=e($electronicInvoiceText('Betreff'))?></dt><dd><?= e($invoiceMessage['subject']) ?></dd><dt><?=e($electronicInvoiceText('Datum laut E-Mail'))?></dt><dd><?= e($invoiceMessage['date']) ?></dd></dl><?php if($invoiceMessage['truncated']): ?><p><?=e($electronicInvoiceText('Begrenzte Vorschau einer großen E-Mail. Den vollständigen Inhalt enthält die Originaldatei.'))?></p><?php endif ?><p><?=e($electronicInvoiceText('Nachrichteninhalt des Absenders; Angaben nicht automatisch geprüft.'))?> <?= $invoiceMessage['html_converted']?e($electronicInvoiceText('HTML wurde in einfachen Text umgewandelt.')):'' ?></p><div class="doc-path" data-invoice-mail-body><?=nl2br(e($invoiceMessage['body_missing']?$electronicInvoiceText($invoiceMessage['body']):$invoiceMessage['body']))?></div><p><a class="btn btn-outline theme-secondary button secondary" href="<?= e(url(['invoice_mail_original'=>$mailDocumentId,'mail_key'=>$invoiceMessage['mailbox_key'],'mail_uid'=>$invoiceMessage['message_uid']])) ?>"><?=e($electronicInvoiceText('Original-E-Mail herunterladen (.eml)'))?></a></p><?php endif ?></section>
<?php endforeach ?>
